package com.aoo.bcg.gamespi.fsm;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class StateTransitionTableTest{enum Event{OPEN,START,SETTLE} @Test void declaresSourceEventTargetGuardAndSideEffect(){var table=new StateTransitionTable<RoomLifecycleState,Event>(List.of(new StateTransition<>(RoomLifecycleState.CREATED,Event.OPEN,RoomLifecycleState.WAITING,"roomConfigured","publishRoomOpened"),new StateTransition<>(RoomLifecycleState.WAITING,Event.START,RoomLifecycleState.PLAYING,"allReady","dealCards")));List<String>effects=new ArrayList<>();assertEquals(RoomLifecycleState.WAITING,table.transition(RoomLifecycleState.CREATED,Event.OPEN,name->name.equals("roomConfigured"),effects::add));assertEquals(List.of("publishRoomOpened"),effects);assertThrows(IllegalStateException.class,()->table.require(RoomLifecycleState.PLAYING,Event.SETTLE));}}
